{
  "name": "Sunpower CryoTel GT 低温制冷机",
  "name_en": "Sunpower CryoTel GT Cryocooler",
  "manufacturer": "Sunpower",
  "description": "Sunpower CryoTel GT 系列闭循环低温制冷设备（含控制器），用于在实验室中为冷台/低温组件提供冷量并将温度稳定在设定值附近。设备可读取当前温度与功率等运行状态，并支持以温度或功率模式进行基本控制与启停管理。",
  "description_en": "The Sunpower CryoTel GT is a closed-cycle cryocooler (with controller) used in laboratories to provide cooling power for a cold stage/cryogenic assembly and stabilize it near a target temperature. It supports reading operating status such as temperature and power, and basic operation in temperature or power control modes including start/stop control.",
  "actions": [
    {
      "action_name": "auto-at_temperature_band",
      "description": "获取/设置 “到温” 判定温度带宽（K）",
      "description_en": "get/set the “at-temperature” temperature band (K)"
    },
    {
      "action_name": "auto-control_mode",
      "description": "获取/设置 控制模式（功率模式/温度模式）",
      "description_en": "get/set the control mode (power mode / temperature mode)"
    },
    {
      "action_name": "auto-ki",
      "description": "获取/设置 温度控制回路积分系数 Ki",
      "description_en": "get/set the temperature control loop integral constant (Ki)"
    },
    {
      "action_name": "auto-kp",
      "description": "获取/设置 温度控制回路比例系数 Kp",
      "description_en": "get/set the temperature control loop proportional constant (Kp)"
    },
    {
      "action_name": "auto-power_max",
      "description": "获取/设置 用户定义的最大功率上限（W）",
      "description_en": "get/set the user-defined maximum power limit (W)"
    },
    {
      "action_name": "auto-power_min",
      "description": "获取/设置 用户定义的最小功率下限（W）",
      "description_en": "get/set the user-defined minimum power limit (W)"
    },
    {
      "action_name": "auto-power_setpoint",
      "description": "获取/设置 功率设定值（W）",
      "description_en": "get/set the power setpoint (W)"
    },
    {
      "action_name": "auto-query",
      "description": "向制冷机控制器发送查询/设定指令并读取返回",
      "description_en": "send a query/set command to the cryocooler controller and read the response"
    },
    {
      "action_name": "auto-query_multiline",
      "description": "向制冷机控制器发送会返回多行数据的查询并读取返回",
      "description_en": "send a query that returns multiple lines and read the response"
    },
    {
      "action_name": "auto-reset",
      "description": "将制冷机控制器参数复位到出厂默认值",
      "description_en": "reset the cryocooler controller to factory defaults"
    },
    {
      "action_name": "auto-save_control_mode",
      "description": "保存当前控制模式为上电默认模式",
      "description_en": "save the current control mode as the power-up default"
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向制冷机控制器发送指令（不读取返回值）",
      "description_en": "send a command to the cryocooler controller (no response readback)"
    },
    {
      "action_name": "auto-stop",
      "description": "获取/设置 停机状态（停止/启动）",
      "description_en": "get/set the stop state (stop/start)"
    },
    {
      "action_name": "auto-stop_mode",
      "description": "获取/设置 停机控制来源模式",
      "description_en": "get/set the stop control source mode"
    },
    {
      "action_name": "auto-temperature_setpoint",
      "description": "获取/设置 温度设定值（K）",
      "description_en": "get/set the temperature setpoint (K)"
    },
    {
      "action_name": "auto-thermostat",
      "description": "获取/设置 恒温器（thermostat）模式开关",
      "description_en": "get/set the thermostat mode enable/disable"
    },
    {
      "action_name": "auto-errors",
      "description": "获取 当前活动的错误代码列表",
      "description_en": "get the list of currently active error codes"
    },
    {
      "action_name": "auto-power",
      "description": "获取 当前功率（W）",
      "description_en": "get the current power (W)"
    },
    {
      "action_name": "auto-power_current_and_limits",
      "description": "获取 当前功率及在当前温度下允许的功率上下限（W）",
      "description_en": "get the current power and the allowable power limits at the current temperature (W)"
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取 设备序列号与修订版本信息",
      "description_en": "get the device serial number and revision information"
    },
    {
      "action_name": "auto-state",
      "description": "获取 控制器主要控制参数及其当前值列表",
      "description_en": "get a list of controller control parameters and their current values"
    },
    {
      "action_name": "auto-temperature",
      "description": "获取 当前温度（K）",
      "description_en": "get the current temperature (K)"
    },
    {
      "action_name": "auto-thermostat_status",
      "description": "获取 恒温器（thermostat）当前状态（开/关）",
      "description_en": "get the current thermostat status (on/off)"
    }
  ],
  "tag_hints": [
    "cryocooler",
    "closed-cycle cryogenic cooling",
    "CryoTel GT",
    "temperature setpoint control",
    "power control (W)",
    "cryogenic instrumentation",
    "serial (RS-232/serial) control"
  ]
}
